        ["Este nodo ya es el dispositivo funcional."] = ("This node is already the functional device.", "Este nó já é o dispositivo funcional.", "Dieser Knoten ist bereits das funktionale Gerät.", "Ce nœud est déjà le périphérique fonctionnel."),
        ["Funciones del producto: {0}"] = ("Product functions: {0}", "Funções do produto: {0}", "Produktfunktionen: {0}", "Fonctions du produit : {0}"),
        ["No hay dispositivos de este tipo conectados ahora."] = ("No devices of this type are currently connected.", "Nenhum dispositivo deste tipo está conectado agora.", "Aktuell sind keine Geräte dieses Typs angeschlossen.", "Aucun périphérique de ce type n'est actuellement connecté."),

        ["No se pudo determinar la controladora de host USB."] = ("Could not determine the USB host controller.", "Não foi possível determinar o controlador de host USB.", "Der USB-Host-Controller konnte nicht ermittelt werden.", "Impossible de déterminer le contrôleur hôte USB."),

        ["Reiniciar dispositivo"] = ("Restart device", "Reiniciar dispositivo", "Gerät neu starten", "Redémarrer le périphérique"),
        ["Instalar servicio"] = ("Install service", "Instalar serviço", "Dienst installieren", "Installer le service"),
        ["Reinstalar servicio"] = ("Reinstall service", "Reinstalar serviço", "Dienst neu installieren", "Réinstaller le service"),
        ["Seleccioná un dispositivo de la lista para usar estas acciones."] = ("Select a device from the list to use these actions.", "Selecione um dispositivo da lista para usar estas ações.", "Wählen Sie ein Gerät aus der Liste, um diese Aktionen zu nutzen.", "Sélectionnez un périphérique dans la liste pour utiliser ces actions."),
        ["Tasa de sondeo a aplicar al dispositivo seleccionado"] = ("Polling rate to apply to the selected device", "Taxa de polling a aplicar ao dispositivo selecionado", "Abfragerate, die auf das ausgewählte Gerät angewendet wird", "Fréquence d'interrogation à appliquer au périphérique sélectionné"),
        ["Dispositivo reiniciado."] = ("Device restarted.", "Dispositivo reiniciado.", "Gerät neu gestartet.", "Périphérique redémarré."),
        ["No se pudo reiniciar el dispositivo."] = ("Could not restart the device.", "Não foi possível reiniciar o dispositivo.", "Das Gerät konnte nicht neu gestartet werden.", "Impossible de redémarrer le périphérique."),

        ["Componente instalado. Ahora podés ajustar la tasa de cualquier dispositivo."] = ("Component installed. You can now adjust the rate of any device.", "Componente instalado. Agora você pode ajustar a taxa de qualquer dispositivo.", "Komponente installiert. Sie können nun die Rate jedes Geräts anpassen.", "Composant installé. Vous pouvez maintenant ajuster la fréquence de n'importe quel périphérique."),

        ["Se listaron {0} dispositivos pero sin nombre hijo ni controladora (parece una versión vieja del programa)."] = ("{0} devices were listed but without child name or controller (looks like an old program version).", "{0} dispositivos foram listados, mas sem nome filho nem controlador (parece uma versão antiga do programa).", "{0} Geräte wurden ohne untergeordneten Namen und ohne Controller aufgelistet (sieht nach einer alten Programmversion aus).", "{0} périphériques listés mais sans nom enfant ni contrôleur (semble être une ancienne version du programme)."),

