        ["Desarrollo"] = ("Development", "Desenvolvimento", "Entwicklung", "Développement"),
        ["Personaliza el comportamiento de WHPO. Los cambios se guardan automáticamente."] = ("Customize WHPO behavior. Changes are saved automatically.", "Personalize o comportamento do WHPO. As alterações são salvas automaticamente.", "Passen Sie das Verhalten von WHPO an. Änderungen werden automatisch gespeichert.", "Personnalisez le comportement de WHPO. Les modifications sont enregistrées automatiquement."),
        ["Apariencia"] = ("Appearance", "Aparência", "Darstellung", "Apparence"),
        ["Tema de la aplicación"] = ("App theme", "Tema do aplicativo", "App-Design", "Thème de l'application"),
        ["Elige entre el tema del sistema, oscuro, claro, rosa/blanco o negro/azul."] = ("Choose between the system theme, dark, light, pink/white or black/blue.", "Escolha entre o tema do sistema, escuro, claro, rosa/branco ou preto/azul.", "Wählen Sie zwischen Systemdesign, Dunkel, Hell, Rosa/Weiß oder Schwarz/Blau.", "Choisissez entre le thème du système, sombre, clair, rose/blanc ou noir/bleu."),
