        ["Iniciar con Windows"] = ("Start with Windows", "Iniciar com o Windows", "Mit Windows starten", "Démarrer avec Windows"),
        ["Iniciar minimizado"] = ("Start minimized", "Iniciar minimizado", "Minimiert starten", "Démarrer réduit"),
        ["Minimizar a la bandeja"] = ("Minimize to tray", "Minimizar para a bandeja", "In die Taskleiste minimieren", "Réduire dans la barre d'état"),
        ["Al minimizar la ventana, WHPO seguirá ejecutándose desde el área de notificación."] = ("When the window is minimized, WHPO keeps running from the notification area.", "Ao minimizar a janela, o WHPO continuará em execução na área de notificação.", "Wenn das Fenster minimiert wird, läuft WHPO in der Benachrichtigungsleiste weiter.", "Lorsque la fenêtre est réduite, WHPO continue de s'exécuter depuis la zone de notification."),
        ["Optimizar Rendimiento"] = ("Optimize Performance", "Otimizar desempenho", "Leistung optimieren", "Optimiser les performances"),
        ["Prendido (predeterminado): elimina las métricas del ícono y libera la memoria del proceso al minimizar, para que la app consuma lo mínimo en segundo plano. Apagado: el ícono vuelve a mostrar CPU, memoria y temperatura al pasar el cursor."] = ("On (default): removes the icon metrics and frees process memory when minimized, so the app uses as little as possible in the background. Off: the icon shows CPU, memory and temperature again on hover.", "Ligado (padrão): remove as métricas do ícone e libera a memória do processo ao minimizar, para que o aplicativo consuma o mínimo em segundo plano. Desligado: o ícone volta a mostrar CPU, memória e temperatura ao passar o mouse.", "Ein (Standard): entfernt die Metriken aus dem Symbol und gibt Prozessspeicher beim Minimieren frei, damit die App im Hintergrund möglichst wenig verbraucht. Aus: Das Symbol zeigt beim Überfahren wieder CPU, Speicher und Temperatur.", "Activé (par défaut) : supprime les métriques de l'icône et libère la mémoire du processus lors de la réduction, afin que l'application consomme un minimum en arrière-plan. Désactivé : l'icône affiche à nouveau le CPU, la mémoire et la température au survol."),
        ["Logs de desarrollo"] = ("Developer logs", "Logs de desenvolvimento", "Entwicklerprotokolle", "Journaux de développement"),
        ["Registra la actividad de la app en un archivo (app.log). Apagado (predeterminado): no se generan logs. Útil solo para depurar problemas."] = ("Logs app activity to a file (app.log). Off (default): no logs are created. Only useful for debugging.", "Registra a atividade do aplicativo em um arquivo (app.log). Desligado (padrão): nenhum log é criado. Útil apenas para depurar problemas.", "Protokolliert die App-Aktivität in einer Datei (app.log). Aus (Standard): Es werden keine Protokolle erstellt. Nur zum Debuggen nützlich.", "Enregistre l'activité de l'application dans un fichier (app.log). Désactivé (par défaut) : aucun journal n'est créé. Utile uniquement pour le débogage."),
        ["Tamaño de los logs: {0}"] = ("Log size: {0}", "Tamanho dos logs: {0}", "Protokollgröße: {0}", "Taille des journaux : {0}"),
        ["Borrar logs"] = ("Delete logs", "Excluir logs", "Protokolle löschen", "Supprimer les journaux"),
        ["¿Borrar todos los logs de desarrollo? Esta acción no se puede deshacer."] = ("Delete all developer logs? This action cannot be undone.", "Excluir todos os logs de desenvolvimento? Esta ação não pode ser desfeita.", "Alle Entwicklerprotokolle löschen? Diese Aktion kann nicht rückgängig gemacht werden.", "Supprimer tous les journaux de développement ? Cette action est irréversible."),
        ["Logs borrados: {0} liberados."] = ("Logs deleted: {0} freed.", "Logs excluídos: {0} liberados.", "Protokolle gelöscht: {0} freigegeben.", "Journaux supprimés : {0} libérés."),
        ["Abrir carpeta de logs"] = ("Open logs folder", "Abrir pasta de logs", "Protokollordner öffnen", "Ouvrir le dossier des journaux"),
        ["Si WHPO se inicia automáticamente, se abrirá directamente en la bandeja del sistema."] = ("If WHPO starts automatically, it will open directly in the system tray.", "Se o WHPO iniciar automaticamente, ele abrirá diretamente na bandeja do sistema.", "Wenn WHPO automatisch startet, wird es direkt in der Taskleiste geöffnet.", "Si WHPO démarre automatiquement, il s'ouvrira directement dans la barre d'état système."),
        ["Abre WHPO automáticamente cuando iniciás sesión en este equipo."] = ("Launch WHPO automatically when you sign in to this computer.", "Abra o WHPO automaticamente ao entrar neste computador.", "WHPO automatisch starten, wenn Sie sich an diesem Computer anmelden.", "Lancez WHPO automatiquement à la connexion sur cet ordinateur."),
        ["Si está activado, se guarda en el registro del sistema y funciona después de reiniciar el sistema."] = ("If enabled, it is saved in the system registry and works after restarting the system.", "Se ativado, é salvo no registro do sistema e funciona após reiniciar o sistema.", "Wenn aktiviert, wird es in der Registrierung gespeichert und funktioniert nach einem Neustart.", "Si activé, il est enregistré dans le registre système et fonctionne après un redémarrage."),
        ["No se pudo cambiar el inicio con Windows: {0}"] = ("Could not change start with Windows: {0}", "Não foi possível alterar o início com o Windows: {0}", "„Mit Windows starten“ konnte nicht geändert werden: {0}", "Impossible de modifier le démarrage avec Windows : {0}"),
