        ["Plan oficial de Windows para reducir el consumo."] = ("Official Windows plan to reduce power consumption.", "Plano oficial do Windows para reduzir o consumo.", "Offizieller Windows-Plan zur Reduzierung des Stromverbrauchs.", "Plan officiel de Windows pour réduire la consommation."),
