        ["Preset de la comunidad: mínimo 100% para evitar el parking de núcleos y boost agresivo."] = ("Community preset: 100% minimum to avoid core parking and aggressive boost.", "Preset da comunidade: mínimo 100% para evitar o estacionamento de núcleos e boost agressivo.", "Community-Preset: Minimum 100 % gegen Kern-Parking und aggressiver Boost.", "Préréglage Bitsum (Process Lasso/ParkControl) : minimum 100 % pour éviter le stationnement des cœurs et boost agressif."),
        ["Preset de Bitsum para uso general: mínimo 5% y boost eficiente habilitado."] = ("Bitsum preset for general use: 5% minimum and efficient boost enabled.", "Preset da Bitsum para uso geral: mínimo 5% e boost eficiente habilitado.", "Bitsum-Preset für allgemeine Nutzung: Minimum 5 % und effizienter Boost aktiviert.", "Préréglage Bitsum pour usage général : minimum 5 % et boost efficace activé."),
        ["Instalando plan..."] = ("Installing plan...", "Instalando plano...", "Plan wird installiert...", "Installation du plan..."),
        ["No se pudieron cargar los planes instalables."] = ("Could not load installable plans.", "Não foi possível carregar os planos instaláveis.", "Installierbare Pläne konnten nicht geladen werden.", "Impossible de charger les plans installables."),
        ["Plan de energía instalado correctamente."] = ("Power plan installed successfully.", "Plano de energia instalado corretamente.", "Energieplan erfolgreich installiert.", "Plan d'alimentation installé avec succès."),
        ["Plan \"{0}\" instalado correctamente."] = ("Power plan \"{0}\" installed successfully.", "Plano de energia \"{0}\" instalado corretamente.", "Energieplan \"{0}\" erfolgreich installiert.", "Plan d'alimentation « {0} » installé avec succès."),
