        // ===== Reparación =====
        ["Los cambios afectan a todo el sistema y requieren permisos de administrador. Se recomienda reiniciar después de aplicar un perfil."] = ("The changes affect the whole system and require administrator privileges. A restart is recommended after applying a profile.", "As alterações afetam todo o sistema e exigem permissões de administrador. Recomenda-se reiniciar após aplicar um perfil.", "Die Änderungen betreffen das gesamte System und erfordern Administratorrechte. Nach dem Anwenden eines Profils wird ein Neustart empfohlen.", "Les modifications affectent tout le système et nécessitent des privilèges d'administrateur. Un redémarrage est recommandé après l'application d'un profil."),

        // ===== Windows Update =====
        ["Perfiles disponibles"] = ("Available profiles", "Perfis disponíveis", "Verfügbare Profile", "Profils disponibles"),
        ["Tocá una card para seleccionar el perfil y luego aplicálo con el botón de abajo."] = ("Tap a card to select the profile and then apply it with the button below.", "Toque em um card para selecionar o perfil e depois aplique com o botão abaixo.", "Tippen Sie auf eine Karte, um das Profil auszuwählen, und wenden Sie es dann mit der Schaltfläche unten an.", "Appuyez sur une carte pour sélectionner le profil, puis appliquez-le avec le bouton ci-dessous."),
        ["Predeterminado de Windows"] = ("Windows default", "Padrão do Windows", "Windows-Standard", "Défaut Windows"),
        ["Windows por defecto"] = ("Default Windows", "Windows padrão", "Standard-Windows", "Windows par défaut"),
        ["Restaura el comportamiento normal de Windows Update: actualizaciones, controladores y reinicios según los valores predeterminados de Windows."] = ("Restores normal Windows Update behavior: updates, drivers and restarts according to Windows default values.", "Restaura o comportamento normal do Windows Update: atualizações, drivers e reinicializações conforme os valores padrão do Windows.", "Stellt das normale Windows-Update-Verhalten wieder her: Updates, Treiber und Neustarts gemäß den Windows-Standardwerten.", "Rétablit le comportement normal de Windows Update : mises à jour, pilotes et redémarrages selon les valeurs par défaut de Windows."),
        ["Recomendado"] = ("Recommended", "Recomendado", "Empfohlen", "Recommandé"),
        ["Mantiene las actualizaciones de seguridad, evita reinicios automáticos, aplaza las de calidad 4 días y las de versión 365. Los controladores dejan de llegar por Windows Update."] = ("Keeps security updates, avoids automatic restarts, defers quality updates 4 days and version updates 365. Drivers stop arriving through Windows Update.", "Mantém as atualizações de segurança, evita reinicializações automáticas, adia as de qualidade em 4 dias e as de versão em 365. Os drivers deixam de chegar pelo Windows Update.", "Behält Sicherheitsupdates bei, vermeidet automatische Neustarts, verzögert Qualitätsupdates um 4 Tage und Versionsupdates um 365. Treiber kommen nicht mehr über Windows Update.", "Conserve les mises à jour de sécurité, évite les redémarrages automatiques, reporte les mises à jour de qualité de 4 jours et celles de version de 365. Les pilotes n'arrivent plus via Windows Update."),
        ["Desactivar actualizaciones"] = ("Disable updates", "Desativar atualizações", "Updates deaktivieren", "Désactiver les mises à jour"),
        ["Detiene los servicios y tareas de Windows Update, bloquea las automáticas y borra su caché. Sin actualizaciones de seguridad hasta restaurar otro perfil."] = ("Stops Windows Update services and tasks, blocks automatic ones and clears its cache. No security updates until you restore another profile.", "Para os serviços e tarefas do Windows Update, bloqueia os automáticos e limpa o cache. Sem atualizações de segurança até restaurar outro perfil.", "Stoppt Windows-Update-Dienste und -Aufgaben, blockiert automatische und leert den Cache. Keine Sicherheitsupdates, bis Sie ein anderes Profil wiederherstellen.", "Arrête les services et tâches de Windows Update, bloque ceux automatiques et vide son cache. Aucune mise à jour de sécurité jusqu'à la restauration d'un autre profil."),
        ["Aplicar perfil seleccionado"] = ("Apply selected profile", "Aplicar perfil selecionado", "Ausgewähltes Profil anwenden", "Appliquer le profil sélectionné"),
        ["Estado actual"] = ("Current status", "Estado atual", "Aktueller Status", "État actuel"),
        ["Estado actual: {0} · {1}"] = ("Current state: {0} · {1}", "Estado atual: {0} · {1}", "Aktueller Status: {0} · {1}", "État actuel : {0} · {1}"),
        ["Configuración actual"] = ("Current configuration", "Configuração atual", "Aktuelle Konfiguration", "Configuration actuelle"),

