        ["Personalizar"] = ("Customize", "Personalizar", "Anpassen", "Personnaliser"),
        ["Editar nombre"] = ("Edit name", "Editar nome", "Name bearbeiten", "Modifier le nom"),
        ["Guardar nombre"] = ("Save name", "Salvar nome", "Namen speichern", "Enregistrer le nom"),
        ["Sin control"] = ("No control", "Sem controle", "Keine Steuerung", "Sans contrôle"),
        ["Identificando…"] = ("Identifying…", "Identificando…", "Wird identifiziert…", "Identification…"),
        ["Identificar: acelera este canal al 100% unos segundos y después lo devuelve a como estaba. Mirá qué ventilador se acelera para saber cuál es en la placa."] = ("Identify: spins this channel up to 100% for a few seconds and then returns it to how it was. Watch which fan speeds up to tell which one it is on the board.", "Identificar: acelera este canal até 100% por alguns segundos e depois o devolve como estava. Observe qual ventilador acelera para saber qual é na placa.", "Identifizieren: beschleunigt diesen Kanal für ein paar Sekunden auf 100 % und stellt ihn danach wieder her. Beobachten Sie, welcher Lüfter schneller wird, um zu sehen, welcher es auf dem Board ist.", "Identifier : accélère ce canal à 100 % pendant quelques secondes puis le remet comme avant. Regardez quel ventilateur accélère pour savoir lequel c'est sur la carte."),
        ["Añadir punto"] = ("Add point", "Adicionar ponto", "Punkt hinzufügen", "Ajouter un point"),
        ["Reiniciar curva"] = ("Reset curve", "Redefinir curva", "Kurve zurücksetzen", "Réinitialiser la courbe"),
        ["Gráfico y ajustes"] = ("Graph and settings", "Gráfico e ajustes", "Diagramm und Einstellungen", "Graphique et réglages"),
        ["Aplicar esta curva"] = ("Apply this curve", "Aplicar esta curva", "Diese Kurve anwenden", "Appliquer cette courbe"),
        ["{0} puntos"] = ("{0} points", "{0} pontos", "{0} Punkte", "{0} points"),
        ["{0} puntos (silencioso)"] = ("{0} points (quiet)", "{0} pontos (silencioso)", "{0} Punkte (leise)", "{0} points (silencieux)"),
        ["BIOS (auto)"] = ("BIOS (auto)", "BIOS (auto)", "BIOS (auto)", "BIOS (auto)"),
        ["Control"] = ("Control", "Controle", "Steuerung", "Contrôle"),
        ["BIOS (auto): el ventilador lo controla la placa."] = ("BIOS (auto): the motherboard controls this fan.", "BIOS (auto): a placa-mãe controla este ventilador.", "BIOS (auto): Das Mainboard steuert diesen Lüfter.", "BIOS (auto) : la carte mère contrôle ce ventilateur."),
        ["Manual: el ventilador no lo controla la placa."] = ("Manual: the motherboard does not control this fan.", "Manual: a placa-mãe não controla este ventilador.", "Manuell: Das Mainboard steuert diesen Lüfter nicht.", "Manuel : la carte mère ne contrôle pas ce ventilateur."),
        ["Perfil de la curva: los estándar reparten tu curva actual y la escalan hasta el 100 % de uso; los (silencioso) parten de una curva suave y llegan al 85 %; «BIOS (auto)» le devuelve el ventilador al control de la placa."] = ("Curve profile: standard ones spread your current curve and scale it up to 100% usage; the (quiet) ones start from a gentle curve and stop at 85%; “BIOS (auto)” hands the fan back to the motherboard.", "Perfil da curva: os padrão repartem sua curva atual e a escalam até 100 % de uso; os (silencioso) partem de uma curva suave e chegam a 85 %; “BIOS (auto)” devolve o ventilador ao controle da placa-mãe.", "Kurvenprofil: Standard verteilt die aktuelle Kurve und skaliert sie bis 100 % Auslastung; die (leise) starten bei einer sanften Kurve und enden bei 85 %; „BIOS (auto)“ gibt den Lüfter an das Mainboard zurück.", "Profil de la courbe : les standard répartissent la courbe actuelle et la mettent à l'échelle jusqu'à 100 % d'utilisation ; les (silencieux) partent d'une courbe douce et s'arrêtent à 85 % ; « BIOS (auto) » rend le ventilateur à la carte mère."),
        ["Sensor perdido"] = ("Sensor lost", "Sensor perdido", "Sensor verloren", "Capteur perdu"),
        ["Sensor perdido: el canal volvió al BIOS. Reaplicá la curva para retomar el control."] = ("Sensor lost: the channel went back to the BIOS. Reapply the curve to take control again.", "Sensor perdido: o canal voltou ao BIOS. Reaplique a curva para retomar o controle.", "Sensor verloren: der Kanal ist zum BIOS zurückgekehrt. Wende die Kurve erneut an, um die Kontrolle zu übernehmen.", "Capteur perdu : le canal est revenu au BIOS. Réappliquez la courbe pour reprendre le contrôle."),
        ["Histéresis °C"] = ("Hysteresis °C", "Histerese °C", "Hysterese °C", "Hystérésis °C"),
        ["Respuesta s"] = ("Response s", "Resposta s", "Antwort s", "Réponse s"),
        ["Subida %"] = ("Step up %", "Subida %", "Anstieg %", "Montée %"),
        ["Bajada %"] = ("Step down %", "Descida %", "Abfall %", "Descente %"),
        ["Histéresis (°C): el uso no cambia hasta que la temperatura se aleje más que esta banda de donde cambió por última vez. 0 la desactiva; en los extremos de la curva se ignora."] = ("Hysteresis (°C): usage does not change until the temperature moves farther than this band from where it last changed. 0 disables it; it is ignored at the curve's extremes.", "Histerese (°C): o uso não muda até a temperatura se afastar mais que esta faixa de onde mudou pela última vez. 0 a desativa; nos extremos da curva é ignorada.", "Hysterese (°C): die Nutzung ändert sich erst, wenn die Temperatur weiter als dieses Band von der letzten Änderung abweicht. 0 deaktiviert sie; an den Kurvenenden wird sie ignoriert.", "Hystérésis (°C) : l'usage ne change que si la température s'écarte de plus que cette bande depuis le dernier changement. 0 la désactive ; elle est ignorée aux extrémités de la courbe."),
        ["Tiempo de respuesta (s): cuántos segundos tiene que sostenerse un cambio de temperatura antes de aplicarlo. 0 lo desactiva; en los extremos de la curva se ignora."] = ("Response time (s): how many seconds a temperature change must hold before it is applied. 0 disables it; it is ignored at the curve's extremes.", "Tempo de resposta (s): quantos segundos uma mudança de temperatura precisa se manter antes de ser aplicada. 0 o desativa; nos extremos da curva é ignorado.", "Antwortzeit (s): wie viele Sekunden eine Temperaturänderung anhalten muss, bevor sie angewendet wird. 0 deaktiviert sie; an den Kurvenenden wird sie ignoriert.", "Temps de réponse (s) : combien de secondes un changement de température doit tenir avant d'être appliqué. 0 le désactive ; il est ignoré aux extrémités de la courbe."),
        ["Subida máxima de uso por actualización (cada 2 s): suaviza los cambios bruscos. 0 = sin límite."] = ("Maximum usage step up per refresh (every 2 s): smooths abrupt changes. 0 = no limit.", "Subida máxima de uso por atualização (a cada 2 s): suaviza mudanças bruscas. 0 = sem limite.", "Maximaler Anstieg der Nutzung pro Aktualisierung (alle 2 s): glättet abrupte Änderungen. 0 = kein Limit.", "Montée maximale de l'usage par actualisation (toutes les 2 s) : lisse les changements brusques. 0 = sans limite."),
        ["Bajada máxima de uso por actualización (cada 2 s): suaviza los cambios bruscos. 0 = sin límite."] = ("Maximum usage step down per refresh (every 2 s): smooths abrupt changes. 0 = no limit.", "Descida máxima de uso por atualização (a cada 2 s): suaviza mudanças bruscas. 0 = sem limite.", "Maximaler Abfall der Nutzung pro Aktualisierung (alle 2 s): glättet abrupte Änderungen. 0 = kein Limit.", "Descente maximale de l'usage par actualisation (toutes les 2 s) : lisse les changements brusques. 0 = sans limite."),
        ["Soltar al BIOS"] = ("Hand back to BIOS", "Devolver ao BIOS", "An das BIOS zurückgeben", "Rendre au BIOS"),
        ["Curva activa: controla este ventilador"] = ("Active curve: it controls this fan", "Curva ativa: controla este ventilador", "Aktive Kurve: steuert diesen Lüfter", "Courbe active : contrôle ce ventilateur"),
        ["Sin aplicar: el canal sigue el BIOS"] = ("Not applied: the channel still follows the BIOS", "Sem aplicar: o canal segue o BIOS", "Nicht angewendet: der Kanal folgt weiter dem BIOS", "Non appliquée : le canal suit encore le BIOS"),
        ["Tu curva"] = ("Your curve", "Sua curva", "Deine Kurve", "Votre courbe"),
        ["Automático (relevada): {0}–{1} °C · {2} puntos"] = ("Auto (learned): {0}–{1} °C · {2} points", "Automático (relevada): {0}–{1} °C · {2} pontos", "Auto (gelernt): {0}–{1} °C · {2} Punkte", "Auto (relevée) : {0}–{1} °C · {2} points"),
        ["Automático: sin datos todavía — se releva solo con el canal en Automático (sin tu curva)."] = ("Auto: no data yet — it is only learned while the channel is on Auto (without your curve).", "Automático: sem dados ainda — só é relevado com o canal em Automático (sem a sua curva).", "Auto: noch keine Daten — wird nur gelernt, solange der Kanal auf Auto steht (ohne deine Kurve).", "Auto : pas encore de données — la courbe n'est relevée que si le canal est en auto (sans votre courbe)."),
        ["Usar la de la placa"] = ("Use board curve", "Usar a da placa", "Board-Kurve übernehmen", "Utiliser celle de la carte"),
        ["Volver a relevar"] = ("Relearn", "Relevar novamente", "Neu lernen", "Relever à nouveau"),
        ["Arrastrá un punto para moverlo (temperatura y uso); doble clic sobre el gráfico agrega uno nuevo."] = ("Drag a point to move it (temperature and usage); double-click the graph to add a new one.", "Arraste um ponto para movê-lo (temperatura e uso); duplo clique no gráfico adiciona um novo.", "Ziehe einen Punkt, um ihn zu verschieben (Temperatur und Nutzung); Doppelklick auf das Diagramm fügt einen neuen hinzu.", "Faites glisser un point pour le déplacer (température et utilisation) ; double-cliquez sur le graphique pour en ajouter un."),
        ["sin señal"] = ("no signal", "sem sinal", "kein Signal", "aucun signal"),
        ["Auto (BIOS)"] = ("Auto (BIOS)", "Auto (BIOS)", "Auto (BIOS)", "Auto (BIOS)"),
        ["Automático"] = ("Automatic", "Automático", "Automatisch", "Automatique"),
        ["Todos al automático (BIOS)"] = ("All to auto (BIOS)", "Todos ao automático (BIOS)", "Alle auf automatisch (BIOS)", "Tout en automatique (BIOS)"),
        ["Descargando e instalando PawnIO…"] = ("Downloading and installing PawnIO…", "Baixando e instalando o PawnIO…", "PawnIO wird heruntergeladen und installiert…", "Téléchargement et installation de PawnIO…"),
        ["Renombrar ventilador"] = ("Rename fan", "Renomear ventilador", "Lüfter umbenennen", "Renommer le ventilateur"),
        ["Nombre del ventilador:"] = ("Fan name:", "Nome do ventilador:", "Lüftername:", "Nom du ventilateur :"),
        ["Compatibilidad: {0}"] = ("Compatibility: {0}", "Compatibilidade: {0}", "Kompatibilität: {0}", "Compatibilité : {0}"),
        ["▶ Leyendo sensores..."] = ("▶ Reading sensors...", "▶ Lendo sensores...", "▶ Sensoren werden gelesen...", "▶ Lecture des capteurs..."),
        ["✗ No se pudieron leer los sensores: {0}"] = ("✗ Could not read the sensors: {0}", "✗ Não foi possível ler os sensores: {0}", "✗ Sensoren konnten nicht gelesen werden: {0}", "✗ Impossible de lire les capteurs : {0}"),
        ["✗ LibreHardwareMonitor no disponible en este equipo. Verificá que la app corre como administrador."] = ("✗ LibreHardwareMonitor is not available on this machine. Make sure the app is running as administrator.", "✗ LibreHardwareMonitor indisponível nesta máquina. Verifique se o aplicativo está sendo executado como administrador.", "✗ LibreHardwareMonitor ist auf diesem Rechner nicht verfügbar. Stellen Sie sicher, dass die App als Administrator ausgeführt wird.", "✗ LibreHardwareMonitor n'est pas disponible sur cette machine. Vérifiez que l'application s'exécute en tant qu'administrateur."),
        ["ℹ No se detectaron sensores en este equipo."] = ("ℹ No sensors were detected on this machine.", "ℹ Nenhum sensor foi detectado nesta máquina.", "ℹ Auf diesem Rechner wurden keine Sensoren erkannt.", "ℹ Aucun capteur détecté sur cette machine."),

        // ===== Bandeja =====
        ["Salir"] = ("Exit", "Sair", "Beenden", "Quitter"),
        ["en segundo plano"] = ("running in background", "em segundo plano", "im Hintergrund", "en arrière-plan"),
        ["Mostrar métricas en bandeja"] = ("Show tray metrics", "Mostrar métricas na bandeja", "Metriken im Infobereich anzeigen", "Afficher les métriques dans la zone de notification"),
        ["Prendido: el ícono de la bandeja muestra uso de CPU, memoria y temperatura al pasar el cursor, con sondeos periódicos de hardware que elevan el consumo de CPU de la app en segundo plano. Apagado (predeterminado): sin métricas; al ocultar la ventana se libera la memoria del proceso para un consumo mínimo."] = ("On: the tray icon shows CPU, memory and temperature usage on hover, with periodic hardware polling that raises the app's background CPU usage. Off (default): no metrics; memory is freed when the window is hidden for a minimal footprint.", "Ligado: o ícone da bandeja mostra uso de CPU, memória e temperatura ao passar o cursor, com sondagens periódicas de hardware que elevam o consumo de CPU do app em segundo plano. Desligado (padrão): sem métricas; ao ocultar a janela, a memória do processo é liberada para um consumo mínimo.", "Ein: Das tray-Symbol zeigt CPU-, Arbeitsspeicher- und Temperaturauslastung beim Überfahren an, mit periodischen Hardware-Abfragen, die die CPU-Last der App im Hintergrund erhöhen. Aus (Standard): keine Metriken; beim Ausblenden des Fensters wird der Arbeitsspeicher freigegeben.", "Activé : l'icône de la zone de notification affiche l'utilisation CPU, mémoire et température au survol, avec des sondages matériels périodiques qui augmentent la consommation CPU de l'app en arrière-plan. Désactivé (par défaut) : pas de métriques ; la mémoire est libérée au masquage de la fenêtre."),
