        ["Solo si no usas cifrado de disco"] = ("Only if you don't use disk encryption", "Somente se você não usar criptografia de disco", "Nur wenn Sie keine Festplattenverschlüsselung verwenden", "Uniquement si vous n'utilisez pas le chiffrement de disque"),
        ["Solo dual-boot con Linux"] = ("Only for Linux dual-boot", "Somente dual-boot com Linux", "Nur bei Linux-Dual-Boot", "Uniquement en double démarrage avec Linux"),
