        ["Requiere permisos de administrador"] = ("Requires administrator privileges", "Requer permissões de administrador", "Erfordert Administratorrechte", "Nécessite des privilèges administrateur"),
        ["Solo hardware Razer"] = ("Razer hardware only", "Somente hardware Razer", "Nur Razer-Hardware", "Uniquement du matériel Razer"),
