        ["Requiere descargar O&O ShutUp10++"] = ("Requires downloading O&O ShutUp10++", "Requer baixar o O&O ShutUp10++", "Erfordert das Herunterladen von O&O ShutUp10++", "Nécessite de télécharger O&O ShutUp10++"),
