        ["Tweaks recomendados para todos los sistemas"] = ("Recommended tweaks for all systems", "Tweaks recomendados para todos os sistemas", "Empfohlene Tweaks für alle Systeme", "Réglages recommandés pour tous les systèmes"),
        ["Requieren precaución, verificar compatibilidad"] = ("Require caution, check compatibility", "Requerem cuidado, verifique a compatibilidade", "Erfordern Vorsicht, Kompatibilität prüfen", "Nécessitent de la prudence, vérifiez la compatibilité"),
        ["Essential Tweaks"] = ("Essential Tweaks", "Tweaks Essenciais", "Wesentliche Tweaks", "Réglages essentiels"),
