        // ===== Windows Update (políticas de Core) =====
        ["Actualizaciones desactivadas"] = ("Updates disabled", "Atualizações desativadas", "Updates deaktiviert", "Mises à jour désactivées"),
        ["Modo recomendado"] = ("Recommended mode", "Modo recomendado", "Empfohlener Modus", "Mode recommandé"),
        ["Actualizaciones de seguridad activas, control de reinicios y aplazamiento de versiones nuevas."] = ("Security updates active, restart control and deferral of new versions.", "Atualizações de segurança ativas, controle de reinicializações e adiamento de novas versões.", "Sicherheitsupdates aktiv, Neustartkontrolle und Aufschieben neuer Versionen.", "Mises à jour de sécurité actives, contrôle des redémarrages et report des nouvelles versions."),
        ["Configuración personalizada"] = ("Custom configuration", "Configuração personalizada", "Benutzerdefinierte Konfiguration", "Configuration personnalisée"),
        ["Se detectaron políticas de Windows Update distintas de los tres perfiles de WHPO."] = ("Windows Update policies different from the three WHPO profiles were detected.", "Foram detectadas políticas de Windows Update diferentes dos três perfis do WHPO.", "Es wurden Windows-Update-Richtlinien erkannt, die sich von den drei WHPO-Profilen unterscheiden.", "Des stratégies Windows Update différentes des trois profils WHPO ont été détectées."),
        ["Windows administra las actualizaciones con su configuración habitual."] = ("Windows manages updates with its usual configuration.", "O Windows gerencia as atualizações com sua configuração usual.", "Windows verwaltet Updates mit seiner üblichen Konfiguration.", "Windows gère les mises à jour avec sa configuration habituelle."),
        ["Estado no disponible"] = ("Status unavailable", "Estado indisponível", "Status nicht verfügbar", "État indisponible"),
        ["No fue posible leer las políticas locales de Windows Update."] = ("Could not read the local Windows Update policies.", "Não foi possível ler as políticas locais de Windows Update.", "Die lokalen Windows-Update-Richtlinien konnten nicht gelesen werden.", "Impossible de lire les stratégies locales de Windows Update."),
        ["Se restauraron los valores predeterminados de Windows Update."] = ("Windows Update default values were restored.", "Os valores padrão de Windows Update foram restaurados.", "Die Windows-Update-Standardwerte wurden wiederhergestellt.", "Les valeurs par défaut de Windows Update ont été restaurées."),
        ["Se aplicó el perfil recomendado de Windows Update."] = ("The recommended Windows Update profile was applied.", "O perfil recomendado de Windows Update foi aplicado.", "Das empfohlene Windows-Update-Profil wurde angewendet.", "Le profil recommandé de Windows Update a été appliqué."),
        ["Windows Update fue desactivado."] = ("Windows Update was disabled.", "O Windows Update foi desativado.", "Windows Update wurde deaktiviert.", "Windows Update a été désactivé."),
        ["El modo personalizado no se puede aplicar."] = ("The custom mode cannot be applied.", "O modo personalizado não pode ser aplicado.", "Der benutzerdefinierte Modus kann nicht angewendet werden.", "Le mode personnalisé ne peut pas être appliqué."),
        ["Esta función solo está disponible en Windows."] = ("This feature is only available on Windows.", "Este recurso só está disponível no Windows.", "Diese Funktion ist nur unter Windows verfügbar.", "Cette fonctionnalité n'est disponible que sous Windows."),
        ["Se requieren permisos de administrador para cambiar Windows Update."] = ("Administrator privileges are required to change Windows Update.", "São necessárias permissões de administrador para alterar o Windows Update.", "Zum Ändern von Windows Update sind Administratorrechte erforderlich.", "Des privilèges administrateur sont requis pour modifier Windows Update."),
        ["No se pudo completar el cambio de Windows Update."] = ("Could not complete the Windows Update change.", "Não foi possível concluir a alteração do Windows Update.", "Die Windows-Update-Änderung konnte nicht abgeschlossen werden.", "Impossible de terminer la modification de Windows Update."),
        ["Configuración aplicada"] = ("Configuration applied", "Configuração aplicada", "Konfiguration angewendet", "Configuration appliquée"),
        ["No se pudo aplicar la configuración"] = ("Could not apply the configuration", "Não foi possível aplicar a configuração", "Konfiguration konnte nicht angewendet werden", "Impossible d'appliquer la configuration"),
        ["Reinicia el equipo para completar todos los cambios."] = ("Restart the computer to complete all changes.", "Reinicie o computador para concluir todas as alterações.", "Starten Sie den Computer neu, um alle Änderungen abzuschließen.", "Redémarrez l'ordinateur pour terminer toutes les modifications."),
        ["Algunos componentes informaron advertencias; consulta el registro de WHPO para más detalles."] = ("Some components reported warnings; check the WHPO log for more details.", "Alguns componentes relataram avisos; consulte o log do WHPO para mais detalhes.", "Einige Komponenten meldeten Warnungen; weitere Details finden Sie im WHPO-Protokoll.", "Certains composants ont signalé des avertissements ; consultez le journal WHPO pour plus de détails."),
