        ["No se encontró ningún adaptador de red activo. Se abrirá la configuración de red."] = ("No active network adapter was found. Network settings will open.", "Nenhum adaptador de rede ativo foi encontrado. As configurações de rede serão abertas.", "Kein aktiver Netzwerkadapter gefunden. Die Netzwerkeinstellungen werden geöffnet.", "Aucun adaptateur réseau actif trouvé. Les paramètres réseau vont s'ouvrir."),
        ["Test completado: {0}% de pérdida ({1} de {2} paquetes perdidos)."] = ("Test completed: {0}% loss ({1} of {2} packets lost).", "Teste concluído: {0}% de perda ({1} de {2} pacotes perdidos).", "Test abgeschlossen: {0}% Verlust ({1} von {2} Paketen verloren).", "Test terminé : {0}% de perte ({1} sur {2} paquets perdus)."),
