        ["Biblioteca de juegos"] = ("Game library", "Biblioteca de jogos", "Spielebibliothek", "Bibliothèque de jeux"),
        ["Modo juego de WinForge"] = ("WinForge Game Mode", "Modo de jogo da WinForge", "WinForge-Spielmodus", "Mode jeu de WinForge"),
        // El resumen llega VERIFICADO por el servicio: los conteos no son "pedidos
        // enviados" sino los confirmados (servicios que dejaron de correr, procesos
        // que aceptaron la prioridad baja). Los no confirmados se aclaran aparte.
        ["Modo juego: aplicando optimización... esperando confirmación de servicios y procesos."] = ("Game Mode: applying optimization... waiting for confirmation from services and processes.", "Modo jogo: aplicando otimização... aguardando confirmação de serviços e processos.", "Spielmodus: Optimierung wird angewendet... warte auf Bestätigung von Diensten und Prozessen.", "Mode jeu : optimisation en cours... en attente de confirmation des services et des processus."),
        ["Modo juego activo: {0} reglas aplicadas, {1} servicios detenidos, {2} procesos optimizados y {3} procesos cerrados."] = ("Game Mode active: {0} rules applied, {1} services stopped, {2} processes optimized and {3} processes closed.", "Modo jogo ativo: {0} regras aplicadas, {1} serviços parados, {2} processos otimizados e {3} processos fechados.", "Spielmodus aktiv: {0} Regeln angewendet, {1} Dienste beendet, {2} Prozesse optimiert und {3} Prozesse beendet.", "Mode jeu actif : {0} règles appliquées, {1} services arrêtés, {2} processus optimisés et {3} processus fermés."),
        // El boost no encontró nada que hacer en ESTE equipo (no es un fallo): decir
        // "0 servicios, 0 procesos" se leía como si hubiera fallado.
        ["Modo juego activo: no había nada que optimizar."] = ("Game Mode active: there was nothing to optimize.", "Modo jogo ativo: não havia nada para otimizar.", "Spielmodus aktiv: es gab nichts zu optimieren.", "Mode jeu actif : il n'y avait rien à optimiser."),
        ["Modo juego activo: {0} reglas aplicadas. No había servicios ni procesos para optimizar."] = ("Game Mode active: {0} rules applied. There were no services or processes to optimize.", "Modo jogo ativo: {0} regras aplicadas. Não havia serviços ou processos para otimizar.", "Spielmodus aktiv: {0} Regeln angewendet. Es gab keine Dienste oder Prozesse zu optimieren.", "Mode jeu actif : {0} règles appliquées. Il n'y avait aucun service ni processus à optimiser."),


        ["Favoritos ({0})"] = ("Favorites ({0})", "Favoritos ({0})", "Favoriten ({0})", "Favoris ({0})"),
