        ["¿Ocultar {0}? Podés volver a mostrarlo desde la sección Ocultos."] = ("Hide {0}? You can show it again from the Hidden section.", "Ocultar {0}? Você pode exibi-lo novamente na seção Ocultos.", "{0} ausblenden? Du kannst es wieder im Abschnitt „Ausgeblendet“ einblenden.", "Masquer {0} ? Vous pouvez le réafficher depuis la section Masqués."),
        ["Ocultos ({0})"] = ("Hidden ({0})", "Ocultos ({0})", "Ausgeblendet ({0})", "Masqués ({0})"),
