        ["No se pudieron escanear los juegos: {0}"] = ("Could not scan games: {0}", "Não foi possível escanear os jogos: {0}", "Spiele konnten nicht gescannt werden: {0}", "Impossible d'analyser les jeux : {0}"),
        ["Seleccionar el exe del juego"] = ("Select the game executable", "Selecione o executável do jogo", "Spiel ausführbare Datei auswählen", "Sélectionner l'exécutable du jeu"),
        ["No se agregó ningún juego: «{0}» no es un ejecutable."] = ("No game was added: “{0}” is not an executable.", "Nenhum jogo foi adicionado: “{0}” não é um executável.", "Kein Spiel hinzugefügt: „{0}“ ist keine ausführbare Datei.", "Aucun jeu ajouté : « {0} » n'est pas un exécutable."),
        ["Se agregaron {0} juegos. Se omitieron {1} archivos que no son ejecutables."] = ("{0} games were added. {1} non-executable files were skipped.", "{0} jogos foram adicionados. {1} arquivos não executáveis foram ignorados.", "{0} Spiele hinzugefügt. {1} nicht ausführbare Dateien wurden übersprungen.", "{0} jeux ajoutés. {1} fichiers non exécutables ont été ignorés."),
        ["Se agregó «{0}» a la biblioteca."] = ("“{0}” was added to the library.", "“{0}” foi adicionado à biblioteca.", "„{0}“ wurde zur Bibliothek hinzugefügt.", "« {0} » a été ajouté à la bibliothèque."),
        ["Se agregaron {0} juegos a la biblioteca."] = ("{0} games were added to the library.", "{0} jogos foram adicionados à biblioteca.", "{0} Spiele wurden zur Bibliothek hinzugefügt.", "{0} jeux ont été ajoutés à la bibliothèque."),
        ["No se pudo agregar el juego: {0}"] = ("Could not add the game: {0}", "Não foi possível adicionar o jogo: {0}", "Das Spiel konnte nicht hinzugefügt werden: {0}", "Impossible d'ajouter le jeu : {0}"),
        ["Reglas guardadas. Se aplicarán cuando el juego esté en ejecución."] = ("Rules saved. They will apply when the game is running.", "Regras salvas. Elas serão aplicadas quando o jogo estiver em execução.", "Regeln gespeichert. Sie werden angewendet, wenn das Spiel ausgeführt wird.", "Règles enregistrées. Elles s'appliqueront lorsque le jeu sera en cours d'exécution."),
        ["Biblioteca de juegos instalados (Steam/Epic/Ubisoft/EA/Blizzard): marcá favoritos y fijá prioridad de CPU, afinidad de núcleos, prioridad de GPU, prioridad de E/S y plan de energía por juego. Cada ajuste admite «Actual» (solo esta apertura del juego) o «Siempre» (permanente, se guarda en el registro). La estrella lo marca favorito y el engranaje configura sus reglas."] = ("Installed games library (Steam/Epic/Ubisoft/EA/Blizzard): mark favorites and set CPU priority, core affinity, GPU priority, I/O priority and power plan per game. Each setting accepts “Current” (this game session only) or “Always” (permanent, saved in the registry). The star marks it as favorite and the gear configures its rules.", "Biblioteca de jogos instalados (Steam/Epic/Ubisoft/EA/Blizzard): marque favoritos e defina prioridade de CPU, afinidade de núcleos, prioridade de GPU, prioridade de E/S e plano de energia por jogo. Cada ajuste aceita “Atual” (apenas esta abertura do jogo) ou “Sempre” (permanente, salvo no registro). A estrela marca como favorito e a engrenagem configura as regras.", "Bibliothek installierter Spiele (Steam/Epic/Ubisoft/EA/Blizzard): Favoriten markieren und CPU-Priorität, Kernaffinität, GPU-Priorität, E/A-Priorität und Energieplan pro Spiel festlegen. Jede Einstellung akzeptiert „Aktuell“ (nur diese Spielsitzung) oder „Immer“ (dauerhaft, in der Registrierung gespeichert). Der Stern markiert es als Favorit und das Zahnrad konfiguriert die Regeln.", "Bibliothèque de jeux installés (Steam/Epic/Ubisoft/EA/Blizzard) : marquez des favoris et définissez la priorité CPU, l'affinité des cœurs, la priorité GPU, la priorité E/S et le plan d'alimentation par jeu. Chaque réglage accepte « Actuel » (cette session de jeu uniquement) ou « Toujours » (permanent, enregistré dans le registre). L'étoile le marque comme favori et l'engrenage configure ses règles."),
        ["No se encontraron juegos instalados. Probá «Re-detectar» o «Añadir manual»."] = ("No installed games found. Try «Re-detect» or «Add manually».", "Nenhum jogo instalado encontrado. Tente «Redetectar» ou «Adicionar manual».", "Keine installierten Spiele gefunden. Versuchen Sie «Erneut erkennen» oder «Manuell hinzufügen».", "Aucun jeu installé trouvé. Essayez « Re-détecter » ou « Ajouter manuellement »."),
        ["No se encontraron juegos que coincidan con la búsqueda."] = ("No games match your search.", "Nenhum jogo corresponde à sua pesquisa.", "Keine Spiele entsprechen Ihrer Suche.", "Aucun jeu ne correspond à votre recherche."),
