        ["Prioridad E/S actual: {0} ({1})"] = ("Current I/O priority: {0} ({1})", "Prioridade de E/S atual: {0} ({1})", "Aktuelle E/A-Priorität: {0} ({1})", "Priorité E/S actuelle : {0} ({1})"),
        ["Prioridad E/S actual: no se pudo leer (proceso protegido: anti-cheat)"] = ("Current I/O priority: could not read (protected by anti-cheat)", "Prioridade de E/S atual: não foi possível ler (protegido por anti-cheat)", "Aktuelle E/A-Priorität: konnte nicht gelesen werden (durch Anti-Cheat geschützt)", "Priorité E/S actuelle : impossible de lire (protégé par anti-cheat)"),
