        ["No se pudo aplicar {0} en vivo a {1} (proceso protegido o cerrado). {2}"] = ("Could not apply {0} live to {1} (protected or closed process). {2}", "Não foi possível aplicar {0} ao vivo em {1} (processo protegido ou fechado). {2}", "{0} konnte nicht live auf {1} angewendet werden (geschützter oder beendeter Prozess). {2}", "Impossible d'appliquer {0} en direct à {1} (processus protégé ou fermé). {2}"),
