        ["Instalá un emulador de celular para verlo en este apartado y configurarlo a tu gusto!"] = ("Install a mobile emulator to see it in this section and set it up as you like!", "Instale um emulador de celular para vê-lo nesta seção e configurá-lo ao seu gosto!", "Installiere einen Handy-Emulator, um ihn in diesem Abschnitt zu sehen und nach deinen Wünschen einzurichten!", "Installez un émulateur mobile pour le voir dans cette section et le configurer à votre goût !"),
        ["Instalá un emulador de consolas para verlo en este apartado y configurarlo a tu gusto!"] = ("Install a console emulator to see it in this section and set it up as you like!", "Instale um emulador de console para vê-lo nesta seção e configurá-lo ao seu gosto!", "Installiere einen Konsolen-Emulator, um ihn in diesem Abschnitt zu sehen und nach deinen Wünschen einzurichten!", "Installez un émulateur de console pour le voir dans cette section et le configurer à votre goût !"),
        ["Instalá un juego o emulador para verlo en este apartado y configurarlo a tu gusto!"] = ("Install a game or emulator to see it in this section and set it up as you like!", "Instale um jogo ou emulador para vê-lo nesta seção e configurá-lo ao seu gosto!", "Installiere ein Spiel oder einen Emulator, um ihn in diesem Abschnitt zu sehen und nach deinen Wünschen einzurichten!", "Installez un jeu ou un émulateur pour le voir dans cette section et le configurer à votre goût !"),
        ["Instalá un juego para verlo en este apartado y configurarlo a tu gusto!"] = ("Install a game to see it in this section and set it up as you like!", "Instale um jogo para vê-lo nesta seção e configurá-lo ao seu gosto!", "Installiere ein Spiel, um es in diesem Abschnitt zu sehen und nach deinen Wünschen einzurichten!", "Installez un jeu pour le voir dans cette section et le configurer à votre goût !"),
        ["La versión instalada (v{0}) es la más reciente publicada."] = ("The installed version (v{0}) is the latest published one.", "A versão instalada (v{0}) é a mais recente publicada.", "Die installierte Version (v{0}) ist die neueste veröffentlichte.", "La version installée (v{0}) est la plus récente publiée."),
        ["Leyendo el registro, el paquete Appx y los archivos del Modo Juego..."] = ("Reading the registry, the Appx package and the Game Mode files...", "Lendo o registro, o pacote Appx e os arquivos do Modo Jogo...", "Registry, Appx-Paket und Game-Mode-Dateien werden gelesen...", "Lecture du registre, du paquet Appx et des fichiers du Mode Jeu…"),
        ["MTU"] = ("MTU", "MTU", "MTU", "MTU"),
        ["Modo Juego de Windows reactivado: se activará al iniciar un juego."] = ("Windows Game Mode re-enabled: it will turn on when a game starts.", "Modo Jogo do Windows reativado: será ativado ao iniciar um jogo.", "Windows-Game-Mode reaktiviert: wird beim Start eines Spiels aktiviert.", "Mode Jeu de Windows réactivé : il s'activera au lancement d'un jeu."),
        ["No hay procesos agregados. Agregá procesos desde la lista de la izquierda."] = ("No processes added. Add processes from the list on the left.", "Nenhum processo adicionado. Adicione processos pela lista à esquerda.", "Keine Prozesse hinzugefügt. Füge Prozesse aus der Liste links hinzu.", "Aucun processus ajouté. Ajoutez des processus depuis la liste de gauche."),
        ["No hay procesos para cerrar. Agregá procesos desde la lista de la izquierda."] = ("No processes to close. Add processes from the list on the left.", "Nenhum processo para fechar. Adicione processos pela lista à esquerda.", "Keine Prozesse zum Schließen. Füge Prozesse aus der Liste links hinzu.", "Aucun processus à fermer. Ajoutez des processus depuis la liste de gauche."),
        ["No se encontró el launcher Blacksmith. Asegurate de que esté instalado."] = ("Blacksmith launcher not found. Make sure it is installed.", "Launcher Blacksmith não encontrado. Verifique se está instalado.", "Blacksmith-Launcher nicht gefunden. Stelle sicher, dass er installiert ist.", "Launcher Blacksmith introuvable. Assurez-vous qu'il est installé."),
        ["No se pudo abrir la configuración del optimizador. Revisá el log de errores."] = ("Could not open the optimizer settings. Check the error log.", "Não foi possível abrir a configuração do otimizador. Verifique o log de erros.", "Die Einstellungen des Optimierers konnten nicht geöffnet werden. Prüfe das Fehlerprotokoll.", "Impossible d'ouvrir la configuration de l'optimiseur. Consultez le journal d'erreurs."),
        ["No se pudo aplicar {0} en vivo a {1} (proceso protegido o cerrado). La prioridad de CPU queda fijada al nacer por registro."] = ("Could not apply {0} live to {1} (protected or closed process). The CPU priority is set on launch via the registry.", "Não foi possível aplicar {0} ao vivo em {1} (processo protegido ou fechado). A prioridade de CPU fica definida ao iniciar pelo registro.", "{0} konnte nicht live auf {1} angewendet werden (geschützter oder beendeter Prozess). Die CPU-Priorität wird beim Start über die Registry festgelegt.", "Impossible d'appliquer {0} en direct à {1} (processus protégé ou fermé). La priorité CPU est fixée au lancement via le registre."),
        ["No se pudo leer el bInterval del dispositivo."] = ("Could not read the device bInterval.", "Não foi possível ler o bInterval do dispositivo.", "Der bInterval des Geräts konnte nicht gelesen werden.", "Impossible de lire le bInterval de l'appareil."),
        ["Predeterminados (no editables)"] = ("Defaults (not editable)", "Padrões (não editáveis)", "Standard (nicht bearbeitbar)", "Par défaut (non modifiables)"),
        ["Revisá tu conexión a internet e intentá de nuevo."] = ("Check your internet connection and try again.", "Verifique sua conexão à internet e tente novamente.", "Prüfe deine Internetverbindung und versuche es erneut.", "Vérifiez votre connexion Internet et réessayez."),
        ["Se baja la prioridad y se activa el modo ahorro de energía de estos procesos mientras jugás."] = ("These processes get lower priority and power-saving mode while you play.", "Esses processos recebem prioridade menor e modo de economia de energia enquanto você joga.", "Diesen Prozessen wird beim Spielen eine niedrigere Priorität und der Energiesparmodus zugewiesen.", "Ces processus passent en priorité basse et en mode économie d'énergie pendant que vous jouez."),
        ["Se cerró el launcher de {0} — se cancela el lanzamiento."] = ("The {0} launcher was closed — the launch is cancelled.", "O launcher de {0} foi fechado — o lançamento é cancelado.", "Der {0}-Launcher wurde geschlossen — der Start wird abgebrochen.", "Le launcher de {0} a été fermé — le lancement est annulé."),
        ["Se puede instalar la v{0} sobre la actual."] = ("v{0} can be installed over the current one.", "A v{0} pode ser instalada sobre a atual.", "v{0} kann über die aktuelle installiert werden.", "La v{0} peut être installée par-dessus l'actuelle."),
        ["TCPNoDelay + TcpAckFrequency"] = ("TCPNoDelay + TcpAckFrequency", "TCPNoDelay + TcpAckFrequency", "TCPNoDelay + TcpAckFrequency", "TCPNoDelay + TcpAckFrequency"),
        ["bInterval {0} en high-speed: 2^({0}-1) microframes (≈{1} Hz)."] = ("bInterval {0} at high-speed: 2^({0}-1) microframes (≈{1} Hz).", "bInterval {0} em high-speed: 2^({0}-1) microframes (≈{1} Hz).", "bInterval {0} bei High-Speed: 2^({0}-1) Microframes (≈{1} Hz).", "bInterval {0} en high-speed : 2^({0}-1) microframes (≈{1} Hz)."),
        ["bInterval {0}: {0} ms por frame (≈{1} Hz)."] = ("bInterval {0}: {0} ms per frame (≈{1} Hz).", "bInterval {0}: {0} ms por frame (≈{1} Hz).", "bInterval {0}: {0} ms pro Frame (≈{1} Hz).", "bInterval {0} : {0} ms par frame (≈{1} Hz)."),
        ["{0} eliminado de la biblioteca. Al ser manual, no se re-detectará."] = ("{0} removed from the library. Since it is manual, it will not be re-detected.", "{0} removido da biblioteca. Como é manual, não será redetectado.", "{0} aus der Bibliothek entfernt. Da es manuell ist, wird es nicht erneut erkannt.", "{0} retiré de la bibliothèque. Comme il est manuel, il ne sera pas re-détecté."),
        ["{0} eliminado de la biblioteca. Podés re-detectarlo con «Re-detectar»."] = ("{0} removed from the library. You can re-detect it with «Re-detect».", "{0} removido da biblioteca. Você pode redetectá-lo com «Redetectar».", "{0} aus der Bibliothek entfernt. Du kannst es mit «Erneut erkennen» erneut erkennen.", "{0} retiré de la bibliothèque. Vous pouvez le re-détecter avec « Re-détecter »."),
        ["{0} no se pudieron borrar (en uso o sin permisos)."] = ("{0} could not be deleted (in use or without permissions).", "{0} não puderam ser excluídos (em uso ou sem permissões).", "{0} konnten nicht gelöscht werden (in Benutzung oder ohne Berechtigung).", "{0} n'ont pas pu être supprimés (en cours d'utilisation ou sans permissions)."),
        ["¿Borrar {0} archivos permanentemente? Esta acción no se puede deshacer."] = ("Permanently delete {0} files? This action cannot be undone.", "Excluir {0} arquivos permanentemente? Esta ação não pode ser desfeita.", "{0} Dateien dauerhaft löschen? Diese Aktion kann nicht rückgängig gemacht werden.", "Supprimer définitivement {0} fichiers ? Cette action est irréversible."),
        ["¿Eliminar {0} de la biblioteca? No se desinstala. Al ser un juego manual, no volverá a aparecer con «Re-detectar»."] = ("Remove {0} from the library? It is not uninstalled. As a manual game, it will not come back with «Re-detect».", "Remover {0} da biblioteca? O jogo não é desinstalado. Por ser um jogo manual, não voltará a aparecer com «Redetectar».", "{0} aus der Bibliothek entfernen? Es wird nicht deinstalliert. Als manuelles Spiel erscheint es mit «Erneut erkennen» nicht wieder.", "Retirer {0} de la bibliothèque ? Le jeu n'est pas désinstallé. Comme il est manuel, il ne réapparaîtra pas avec « Re-détecter »."),
        ["¿Eliminar {0} de la biblioteca? No se desinstala. Podés re-detectarlo con el botón «Re-detectar»."] = ("Remove {0} from the library? It is not uninstalled. You can re-detect it with the «Re-detect» button.", "Remover {0} da biblioteca? O jogo não é desinstalado. Você pode redetectá-lo com o botão «Redetectar».", "{0} aus der Bibliothek entfernen? Es wird nicht deinstalliert. Du kannst es mit dem Button «Erneut erkennen» erneut erkennen.", "Retirer {0} de la bibliothèque ? Le jeu n'est pas désinstallé. Vous pouvez le re-détecter avec le bouton « Re-détecter »."),
        ["¿Enviar {0} archivos a la papelera de reciclaje?"] = ("Send {0} files to the Recycle Bin?", "Enviar {0} arquivos para a lixeira?", "{0} Dateien in den Papierkorb verschieben?", "Envoyer {0} fichiers à la corbeille ?"),

