        // ===== Vía de audio (WASAPI) =====
        ["Se mide el motor de audio (WASAPI) y la ida y vuelta del impulso: no hace falta tocar nada."] = ("Measures the audio engine (WASAPI) and the impulse round trip: no need to touch anything.", "Mede o motor de áudio (WASAPI) e a ida e volta do impulso: não precisa tocar em nada.", "Misst die Audio-Engine (WASAPI) und den Impuls-Hin-und-zurück-Weg: nichts erforderlich.", "Mesure le moteur audio (WASAPI) et l'aller-retour de l'impulsion : inutile de toucher à quoi que ce soit."),
        ["Ese endpoint de audio ya no está disponible."] = ("That audio endpoint is no longer available.", "Esse endpoint de áudio não está mais disponível.", "Dieser Audio-Endpunkt ist nicht mehr verfügbar.", "Ce point de terminaison audio n'est plus disponible."),
        ["Midiendo el motor de audio (WASAPI)…"] = ("Measuring the audio engine (WASAPI)…", "Medindo o motor de áudio (WASAPI)…", "Audio-Engine wird gemessen (WASAPI)…", "Mesure du moteur audio (WASAPI)…"),
        ["Ida y vuelta: intento {0} de {1}…"] = ("Round trip: attempt {0} of {1}…", "Ida e volta: tentativa {0} de {1}…", "Hin und zurück: Versuch {0} von {1}…", "Aller-retour : essai {0} sur {1}…"),
        ["Medir audio"] = ("Measure audio", "Medir áudio", "Audio messen", "Mesurer l'audio"),
        ["Latencia alta"] = ("High latency", "Latência alta", "Hohe Latenz", "Latence élevée"),
        ["Sin retorno"] = ("No return", "Sem retorno", "Kein Rücksignal", "Pas de retour"),
        ["Ida y vuelta: {0:0.00} ms de mediana sobre {1} intentos (el primer impulso se descarta). Incluye los convertidores del dispositivo: es la latencia que sentís al jugar o en una llamada."] = ("Round trip: {0:0.00} ms median over {1} attempts (the first impulse is discarded). Includes the device converters: it is the latency you feel when gaming or on a call.", "Ida e volta: {0:0.00} ms de mediana sobre {1} tentativas (o primeiro impulso é descartado). Inclui os conversores do dispositivo: é a latência que você sente ao jogar ou numa chamada.", "Hin und zurück: {0:0.00} ms Median über {1} Versuche (der erste Impuls wird verworfen). Enthält die Wandler des Geräts: die spürbare Latenz beim Spielen oder Telefonieren.", "Aller-retour : {0:0.00} ms de médiane sur {1} essais (la première impulsion est écartée). Inclut les convertisseurs de l'appareil : c'est la latence ressentie en jeu ou en appel."),
        ["La ida y vuelta está en el rango típico del hardware de audio: no hay nada que apurar acá."] = ("The round trip is in the typical range for audio hardware: nothing to tune here.", "A ida e volta está na faixa típica do hardware de áudio: nada a ajustar aqui.", "Der Hin-und-zurück-Weg liegt im typischen Bereich der Audio-Hardware: hier gibt es nichts zu optimieren.", "L'aller-retour est dans la plage typique du matériel audio : rien à optimiser ici."),
        ["La ida y vuelta no pudo detectar el retorno: subí el volumen del dispositivo y volvé a medir."] = ("The round trip could not detect the return: raise the device volume and measure again.", "A ida e volta não detectou o retorno: aumente o volume do dispositivo e meça de novo.", "Der Rücklauf wurde nicht erkannt: Lautstärke erhöhen und erneut messen.", "L'aller-retour n'a pas détecté le retour : augmentez le volume de l'appareil et mesurez à nouveau."),
        ["Motor (WASAPI): mediana {0:0.00} ms · período {1:0.00} ms · búfer {2:0.0} ms{3}."] = ("Engine (WASAPI): median {0:0.00} ms · period {1:0.00} ms · buffer {2:0.0} ms{3}.", "Motor (WASAPI): mediana {0:0.00} ms · período {1:0.00} ms · buffer {2:0.0} ms{3}.", "Engine (WASAPI): Median {0:0.00} ms · Periode {1:0.00} ms · Puffer {2:0.0} ms{3}.", "Moteur (WASAPI) : médiane {0:0.00} ms · période {1:0.00} ms · tampon {2:0.0} ms{3}."),

        // ===== Cadencia de bus (teclado, ETW/xHCI) =====
        ["Capturando en el bus: {0} de {1} informes · {2} s restantes. Seguí usando la PC con normalidad."] = ("Capturing on the bus: {0} of {1} reports · {2} s left. Keep using your PC normally.", "Capturando no barramento: {0} de {1} informes · {2} s restantes. Continue usando o PC normalmente.", "Bus-Erfassung: {0} von {1} Berichten · noch {2} s. Nutze den PC normal weiter.", "Capture sur le bus : {0} sur {1} rapports · {2} s restantes. Continuez à utiliser votre PC normalement."),
        // La ventana del bus es fija: el reloj informa cuántos informes lleva sin prometer un corte.
        ["Capturando en el bus: {0} informes · {1} s restantes. Seguí tecleando con normalidad."] = ("Capturing on the bus: {0} reports · {1} s left. Keep typing normally.", "Capturando no barramento: {0} informes · {1} s restantes. Continue digitando normalmente.", "Bus-Erfassung: {0} Berichte · noch {1} s. Tippen Sie normal weiter.", "Capture sur le bus : {0} rapports · {1} s restantes. Continuez à taper normalement."),
        ["Analizando la traza del bus…"] = ("Analyzing the bus trace…", "Analisando o rastro do barramento…", "Bus-Trace wird analysiert…", "Analyse de la trace du bus…"),

