    public static bool HasKey(string es) => All.ContainsKey(es);

    // =========================================================================
    // Paquetes de idioma descargados
    //
    // Un pack es { "texto fuente en español": "traducción" } de UN idioma. Se
    // mergea ACÁ, en el motor, y no en cada llamada: así ninguna de las ~100
    // llamadas a I18n.T cambia y un idioma se activa sin reiniciar la app.
    //
    // Es la ÚNICA vía para todo lo que no sea inglés: la tabla embebida tiene una
    // sola columna traducida, así que pt-BR/de-DE/fr-FR (y los que vengan) se
    // actualizan o agregan publicando un pack, sin recompilar ni republicar la app.
    // =========================================================================

    private static readonly Dictionary<string, Dictionary<string, string>> PackOverlay =
        new(StringComparer.OrdinalIgnoreCase);

    // =========================================================================
    // Textos que traen los componentes (components.json, bloque "i18n")
    //
    // Un componente publica SUS traducciones en el catálogo: { "de-DE": { "name":
    // "…", "description": "…" } }. Se mergean acá igual que un pack, así el nombre
    // y la descripción de una card del Workshop (y la pestaña del navbar, y cualquier
    // diálogo que los muestre) se traducen sin que publicar un componente obligue a
    // tocar la tabla de la app ni a regenerar los packs de idioma.
    //
    // Van SEPARADAS de PackOverlay a propósito: instalar o quitar un pack de idioma
    // no las toca, y se consultan DESPUÉS del pack (el pack sigue siendo la fuente
    // de verdad de su idioma).
    // =========================================================================

    private static readonly Dictionary<string, Dictionary<string, string>> ComponentOverlay =
        new(StringComparer.OrdinalIgnoreCase);

    private static readonly object PackLock = new();

    private static string? _sourceHash;

    /// <summary>
    /// Hash de las claves fuente (contrato de build-language-packs.ps1): sirve para
    /// detectar un pack que quedó viejo porque cambió el texto fuente. Se calcula
    /// una sola vez, la primera vez que se pide.
    /// </summary>
    public static string SourceHash
        => _sourceHash ??= WHPO.Core.Services.LanguagePackService.ComputeSourceHash(All.Keys);

    /// <summary>Cantidad de claves fuente (para el log y los diagnósticos de packs).</summary>
    public static int KeyCount => All.Count;

    public static bool HasPack(string lang)
    {
        lock (PackLock) return PackOverlay.ContainsKey(lang);
    }

    /// <summary>
    /// Registra (o reemplaza) el pack de un idioma. El mapa inverso se reconstruye
    /// en un diccionario NUEVO que se publica de una sola vez: los lectores (que
    /// pueden venir de otros hilos) nunca ven un diccionario a medio escribir.
    /// </summary>
    public static void AddPack(string lang, IEnumerable<KeyValuePair<string, string>> strings)
    {
        if (string.IsNullOrWhiteSpace(lang) || strings == null) return;
        var map = new Dictionary<string, string>(StringComparer.Ordinal);
        foreach (var kv in strings)
        {
            if (string.IsNullOrEmpty(kv.Key)) continue;
            map[kv.Key] = kv.Value ?? "";
        }
        if (map.Count == 0) return;
        lock (PackLock)
        {
            PackOverlay[lang] = map;
            Reverse = BuildReverse();
        }
    }

    public static void RemovePack(string lang)
    {
        lock (PackLock)
        {
            if (!PackOverlay.Remove(lang)) return;
            Reverse = BuildReverse();
        }
    }

    public static void ClearPacks()
    {
        lock (PackLock)
        {
            if (PackOverlay.Count == 0) return;
            PackOverlay.Clear();
            Reverse = BuildReverse();
        }
    }

    /// <summary>
    /// Registra los textos que traen los componentes en el catálogo (components.json,
    /// bloque "i18n") y reconstruye el mapa inverso.
    ///
    /// Se llama al cargar el catálogo del Workshop: a partir de ahí el nombre y la
    /// descripción de un componente se traducen como cualquier otro texto, tanto por
    /// I18n.T como por el recorrido del árbol visual (el navbar se arma al arrancar,
    /// antes de que exista el catálogo: por eso el llamador re-aplica la UI después).
    /// </summary>
    public static void SetComponentStrings(IEnumerable<(string Language, string Source, string Translated)> pairs)
    {
        var overlay = new Dictionary<string, Dictionary<string, string>>(StringComparer.OrdinalIgnoreCase);
        if (pairs != null)
        {
            foreach (var (language, source, translated) in pairs)
            {
                if (string.IsNullOrWhiteSpace(language) || string.IsNullOrWhiteSpace(source)
                    || string.IsNullOrWhiteSpace(translated)) continue;
                if (!overlay.TryGetValue(language, out var map))
                {
                    map = new Dictionary<string, string>(StringComparer.Ordinal);
                    overlay[language] = map;
                }
                map[source] = translated;
            }
        }

        lock (PackLock)
        {
            ComponentOverlay.Clear();
            foreach (var kv in overlay) ComponentOverlay[kv.Key] = kv.Value;
            Reverse = BuildReverse();
        }
    }

    public static bool TryTranslate(string lang, string es, out string result)
    {
        // 1) Pack descargado: es la fuente de verdad de ese idioma (pt-BR, de-DE,
        //    fr-FR y cualquier idioma nuevo llegan por acá).
        if (TryTranslateFromPack(lang, es, out result))
            return true;

        // 2) Textos que trae el propio componente en el catálogo (components.json).
        //    Después del pack: el pack manda sobre su idioma.
        if (TryTranslateFromComponents(lang, es, out result))
            return true;

        // 3) Embebido: la tabla trae inglés, portugués, alemán y francés en línea (el
        //    español es la clave fuente, así que I18n.T la devuelve tal cual antes de
        //    llegar acá). Los idiomas que no están en la tabla —zh-CN, ru-RU— llegan
        //    por pack.
        if (All.TryGetValue(es, out var tr) && TryFromEmbedded(lang, tr, out result))
            return true;

        result = es;
        return false;
    }

    /// <summary>Columna embebida que corresponde a un código de idioma.</summary>
    private static bool TryFromEmbedded(string lang, (string En, string Pt, string De, string Fr) tr, out string result)
    {
        string value = lang switch
        {
            _ when lang.StartsWith("en", StringComparison.OrdinalIgnoreCase) => tr.En,
            _ when lang.StartsWith("pt", StringComparison.OrdinalIgnoreCase) => tr.Pt,
            _ when lang.StartsWith("de", StringComparison.OrdinalIgnoreCase) => tr.De,
            _ when lang.StartsWith("fr", StringComparison.OrdinalIgnoreCase) => tr.Fr,
            _ => ""
        };
        result = value;
        return !string.IsNullOrEmpty(value);
    }

    /// <summary>Busca el texto en el pack del idioma (sin tocar el mapa inverso).</summary>
    private static bool TryTranslateFromPack(string lang, string es, out string result)
        => TryTranslateFromMap(PackOverlay, lang, es, out result);

    /// <summary>
    /// Busca el texto entre los que traen los componentes en el catálogo (mismo
    /// idioma exacto que el pack: los códigos salen de languages.json).
    /// </summary>
    private static bool TryTranslateFromComponents(string lang, string es, out string result)
        => TryTranslateFromMap(ComponentOverlay, lang, es, out result);

    /// <summary>Busca una clave fuente en un overlay (idioma → fuente → traducción).</summary>
    private static bool TryTranslateFromMap(
        Dictionary<string, Dictionary<string, string>> overlay, string lang, string es, out string result)
    {
        result = es;
        Dictionary<string, string>? map;
        lock (PackLock) { overlay.TryGetValue(lang, out map); }
        if (map == null) return false;
        if (map.TryGetValue(es, out var value) && !string.IsNullOrEmpty(value))
        {
            result = value;
            return true;
        }
        return false;
    }

    // Mapa inverso: texto visible (fuente en español o traducción en CUALQUIER
    // idioma) → clave fuente en español. Permite al motor de traducciones reconocer
    // un texto que ya fue traducido (por el recorrido o por código) y revertirlo
    // al idioma actual, incluso si el elemento nunca se registró en español.
    // Se reemplaza entero al instalar/quitar un pack (volatile: lectura sin lock).
    private static volatile Dictionary<string, string> Reverse = BuildReverse();

    private static Dictionary<string, string> BuildReverse()
    {
        var rev = new Dictionary<string, string>(StringComparer.Ordinal);
        foreach (var (es, tr) in All)
        {
            rev.TryAdd(es, es);
            if (!string.IsNullOrEmpty(tr.En)) rev.TryAdd(tr.En, es);
            if (!string.IsNullOrEmpty(tr.Pt)) rev.TryAdd(tr.Pt, es);
            if (!string.IsNullOrEmpty(tr.De)) rev.TryAdd(tr.De, es);
            if (!string.IsNullOrEmpty(tr.Fr)) rev.TryAdd(tr.Fr, es);
        }

        // Textos de los packs y de los componentes: el motor necesita reconocer una
        // traducción ya aplicada (por el recorrido del árbol o por código) y volver a
        // su clave. Los de los componentes también aportan su texto fuente en español
        // (el `name`/`description` de cada entrada del catálogo): sin eso, el recorrido
        // del navbar no reconocería el nombre del componente como un texto traducible.
        List<Dictionary<string, string>> packs;
        lock (PackLock)
            packs = PackOverlay.Values.Concat(ComponentOverlay.Values).ToList();
        foreach (var map in packs)
        {
            foreach (var kv in map)
            {
                rev.TryAdd(kv.Key, kv.Key);
                if (!string.IsNullOrEmpty(kv.Value)) rev.TryAdd(kv.Value, kv.Key);
            }
        }
        return rev;
    }

    /// <summary>Devuelve la clave fuente (español) de un texto visible, o null si no es ni clave ni traducción.</summary>
    public static string? SourceOf(string text)
        => Reverse.TryGetValue(text, out var s) ? s : null;

    /// <summary>True si el texto es una clave (español) o una traducción conocida de alguna clave.</summary>
    public static bool TryGetSource(string text, out string source)
        => Reverse.TryGetValue(text, out source!);
}
